mapper.select:
SELECT sc.id, sc.student_id, sc.class_id, sc.course_id, sc.exam_name, sc.exam_type, sc.score, sc.exam_date, sc.create_time, sc.update_time, sc.is_deleted, s.student_no, s.name AS student_name, s.gender, cl.class_name, co.course_name, co.full_score FROM score sc LEFT JOIN student s ON sc.student_id = s.id AND s.is_deleted = 0 LEFT JOIN `class` cl ON sc.class_id = cl.id AND cl.is_deleted = 0 LEFT JOIN course co ON sc.course_id = co.id AND co.is_deleted = 0 WHERE sc.is_deleted = 0
AND s.name LIKE CONCAT('%', #{studentName}, '%')
AND sc.class_id = #{classId}
AND sc.course_id = #{courseId}
AND sc.exam_name LIKE CONCAT('%', #{examName}, '%')
ORDER BY sc.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM score sc LEFT JOIN student s ON sc.student_id = s.id AND s.is_deleted = 0 WHERE sc.is_deleted = 0
AND s.name LIKE CONCAT('%', #{studentName}, '%')
AND sc.class_id = #{classId}
AND sc.course_id = #{courseId}
AND sc.exam_name LIKE CONCAT('%', #{examName}, '%')

SELECT COUNT(*)
FROM score
WHERE student_id = #{studentId}
  AND exam_name = #{examName}
  AND course_id = #{courseId}
  AND is_deleted = 0
